// ==============================================================================
// Testbench: tb_aead_full.sv
// Project:   Ascon AEAD and Hash Engine (NIST SP 800-232)
// Finding:   F1 fix — exhaustive RTL KAT verification
//
// Description:
//   Loops over ALL 1089 NIST SP 800-232 AEAD-128 Known Answer Test vectors
//   loaded from tb/vectors/aead_kat.mem (generated by scripts/kat_to_vectors.py).
//
//   For each vector:
//     Test A — Encrypt:  feed key/nonce/AD/PT, verify CT and tag bit-exactly.
//     Test B — Decrypt (valid tag):   verify plaintext released, tag_ok=1, error=0.
//     Test C — Decrypt (corrupt tag): verify tag_ok=0, error=1, NO plaintext released.
//     Test D — Decrypt (corrupt CT):  if PT_LEN>0, flip CT byte 0; verify error=1.
//
//   Edge-case lengths 0,1,7,8,9,15,16,17,31,32,33 bytes are present in the
//   NIST KAT set and are exercised automatically.
//
//   Result:
//     Prints running PASS/FAIL count.
//     Writes pass log to results/kat/rtl_aead_full_pass.log.
//     $fatal on first AEAD error.
//
// Memory layout of aead_kat.mem (RECORD_WORDS = 64, little-endian byte packing
// for AD/PT/CT; big-endian for Key/Nonce/Tag):
//   [0]      count
//   [1]      ad_len   (bytes)
//   [2]      pt_len   (bytes)
//   [3]      reserved
//   [4.. 7]  key[127:0]   (word4 = key[127:96])
//   [8..11]  nonce[127:0] (word8 = nonce[127:96])
//   [12..15] tag[127:0]   (word12 = tag[127:96])
//   [16..23] AD  bytes  (little-endian, 8 words = 32 bytes max)
//   [24..31] PT  bytes  (little-endian, 8 words = 32 bytes max)
//   [32..39] CT  bytes  (little-endian, 8 words = 32 bytes max)
//   [40..63] reserved
//
// [SPEC] Requirement: F1 — tb/unit/tb_aead_full.sv must loop over ALL 1089 vectors.
// [ASSUME] Simulation environment: Xilinx XSim (Vivado 2025.1), Windows.
// ==============================================================================

`timescale 1ns / 1ps
`default_nettype wire

module tb_aead_full;

    // -------------------------------------------------------------------------
    // Parameters
    // -------------------------------------------------------------------------
    localparam int NUM_VECTORS    = 1089;
    localparam int RECORD_WORDS   = 64;
    localparam int TOTAL_MEM_WORDS = NUM_VECTORS * RECORD_WORDS; // 69,696

    localparam time CLK_PERIOD = 10ns; // 100 MHz

    // -------------------------------------------------------------------------
    // KAT Memory
    // -------------------------------------------------------------------------
    reg [31:0] kat_mem [0:TOTAL_MEM_WORDS-1];

    // -------------------------------------------------------------------------
    // DUT signals
    // -------------------------------------------------------------------------
    reg         clk;
    reg         rst_n;
    reg         start;
    reg         soft_rst;
    reg         decrypt;
    reg  [31:0] ad_len;
    reg  [31:0] msg_len;
    reg [127:0] key;
    reg [127:0] nonce;
    reg [127:0] expected_tag;

    reg  [63:0] data_in;
    reg         data_in_valid;
    wire        data_in_ready;

    wire [63:0] data_out;
    wire        data_out_valid;
    reg         data_out_ready;

    reg  [ 7:0] pt_rd_addr;
    wire [63:0] pt_rd_data;
    wire        pt_rd_valid;

    wire        busy;
    wire        done;
    wire        error;
    wire        tag_ok;
    wire [127:0] tag_out;
    wire [ 3:0] fsm_state;

    // -------------------------------------------------------------------------
    // Byte-swap helpers (RTL uses little-endian byte order per 64-bit word)
    // -------------------------------------------------------------------------
    function automatic [31:0] bswap32(input [31:0] v);
        bswap32 = {v[7:0], v[15:8], v[23:16], v[31:24]};
    endfunction

    function automatic [63:0] bswap64_from_be32(input [31:0] hi32, input [31:0] lo32);
        // Convert two big-endian 32-bit words to one little-endian 64-bit word.
        // bswap64({hi32,lo32}) = {bswap32(lo32), bswap32(hi32)}
        bswap64_from_be32 = {bswap32(lo32), bswap32(hi32)};
    endfunction

    // Build 128-bit RTL-native value from 4 consecutive big-endian mem words.
    // RTL convention: [63:0] = bswap64(NIST_first_8B), [127:64] = bswap64(NIST_second_8B)
    function automatic [127:0] be_words_to_rtl128(input integer base_word);
        automatic reg [63:0] lo64 = bswap64_from_be32(kat_mem[base_word],   kat_mem[base_word+1]);
        automatic reg [63:0] hi64 = bswap64_from_be32(kat_mem[base_word+2], kat_mem[base_word+3]);
        be_words_to_rtl128 = {hi64, lo64};
    endfunction
    aead_ctrl #(.BUFFER_DEPTH(256)) dut (
        .clk             (clk),
        .rst_n           (rst_n),
        .start           (start),
        .soft_rst        (soft_rst),
        .decrypt         (decrypt),
        .ad_len          (ad_len),
        .msg_len         (msg_len),
        .key             (key),
        .nonce           (nonce),
        .expected_tag    (expected_tag),
        .data_in         (data_in),
        .data_in_valid   (data_in_valid),
        .data_in_ready   (data_in_ready),
        .data_out        (data_out),
        .data_out_valid  (data_out_valid),
        .data_out_ready  (data_out_ready),
        .pt_rd_addr      (pt_rd_addr),
        .pt_rd_data      (pt_rd_data),
        .pt_rd_valid     (pt_rd_valid),
        .busy            (busy),
        .done            (done),
        .error           (error),
        .tag_ok          (tag_ok),
        .tag_out         (tag_out),
        .fsm_state       (fsm_state)
    );

    // -------------------------------------------------------------------------
    // Clock
    // -------------------------------------------------------------------------
    always #(CLK_PERIOD / 2) clk = ~clk;

    // -------------------------------------------------------------------------
    // Watchdog
    // -------------------------------------------------------------------------
    initial begin
        #50_000_000;
        $display("\n[FATAL] Watchdog timeout (50 ms sim)");
        $fatal(1, "tb_aead_full watchdog");
    end

    // -------------------------------------------------------------------------
    // Statistics and log
    // -------------------------------------------------------------------------
    integer total_pass, total_fail;
    integer log_fd;

    // -------------------------------------------------------------------------
    // Helper task: soft reset DUT
    // -------------------------------------------------------------------------
    task dut_reset();
        @(negedge clk);
        soft_rst      = 1'b1;
        start         = 1'b0;
        data_in_valid = 1'b0;
        data_out_ready= 1'b1;
        @(negedge clk);
        soft_rst      = 1'b0;
        @(negedge clk);
    endtask

    // -------------------------------------------------------------------------
    // Helper: build 64-bit streaming word from little-endian byte array
    //   words[] is the flat kat_mem array, base is the first word index,
    //   byte_offset is the byte position within the field (0 = first byte)
    // -------------------------------------------------------------------------
    function automatic [63:0] build_data_word(
        input integer base_word,   // First kat_mem word of this field
        input integer byte_offset  // Byte offset into the field (0-based)
    );
        // Field stored as 8 words, little-endian bytes.
        // Each kat_mem word holds 4 bytes: word[7:0]=byte0, word[15:8]=byte1, etc.
        // 8 data bytes = 2 kat_mem words starting at (base_word + byte_offset/4)
        automatic integer w0 = base_word + (byte_offset / 4);
        automatic integer w1 = w0 + 1;
        automatic reg [31:0] lo, hi;
        lo = (w0 < TOTAL_MEM_WORDS) ? kat_mem[w0] : 32'h0;
        hi = (w1 < TOTAL_MEM_WORDS) ? kat_mem[w1] : 32'h0;
        // data_in[7:0] = byte0, data_in[63:56] = byte7 (little-endian in 64-bit word)
        build_data_word = {hi, lo};
    endfunction

    // -------------------------------------------------------------------------
    // Helper: stream N bytes from a field (little-endian, 8 bytes per beat)
    // -------------------------------------------------------------------------
    task stream_bytes(
        input integer field_base,   // kat_mem base word for this field
        input integer num_bytes     // actual byte count
    );
        integer byte_off;
        reg [63:0] beat;
        if (num_bytes == 0) disable stream_bytes;
        byte_off = 0;
        while (byte_off < num_bytes) begin
            wait (data_in_ready == 1'b1);
            @(negedge clk);
            beat          = build_data_word(field_base, byte_off);
            data_in       = beat;
            data_in_valid = 1'b1;
            @(negedge clk);
            data_in_valid = 1'b0;
            byte_off      = byte_off + 8;
        end
    endtask

    // -------------------------------------------------------------------------
    // Helper: collect ciphertext output words
    // -------------------------------------------------------------------------
    reg [63:0] ct_captured [0:3]; // Up to 32 bytes = 4 x 64-bit words

    task collect_ct(input integer num_bytes);
        integer n_beats, i;
        n_beats = (num_bytes + 7) / 8;
        for (i = 0; i < n_beats; i = i + 1) begin
            wait (data_out_valid == 1'b1);
            @(negedge clk);
            ct_captured[i] = data_out;
            data_out_ready  = 1'b1;
            @(negedge clk);
        end
    endtask

    // -------------------------------------------------------------------------
    // Check: compare captured CT to expected CT from kat_mem
    // -------------------------------------------------------------------------
    function automatic integer ct_matches(
        input integer ct_base,  // kat_mem word base for expected CT
        input integer num_bytes
    );
        integer i;
        reg [63:0] exp_word;
        integer n_beats;
        n_beats = (num_bytes + 7) / 8;
        ct_matches = 1;
        for (i = 0; i < n_beats; i = i + 1) begin
            exp_word = build_data_word(ct_base, i * 8);
            // Mask bytes beyond num_bytes in the last beat
            if (i == n_beats - 1 && (num_bytes % 8) != 0) begin
                // Mask valid bytes only
                automatic integer valid_bytes = num_bytes % 8;
                automatic reg [63:0] mask;
                mask = (64'h1 << (valid_bytes * 8)) - 64'h1;
                if ((ct_captured[i] & mask) !== (exp_word & mask)) ct_matches = 0;
            end else begin
                if (ct_captured[i] !== exp_word) ct_matches = 0;
            end
        end
    endfunction

    // -------------------------------------------------------------------------
    // MAIN TEST SEQUENCE
    // -------------------------------------------------------------------------
    initial begin
        clk           = 1'b0;
        rst_n         = 1'b0;
        start         = 1'b0;
        soft_rst      = 1'b0;
        decrypt       = 1'b0;
        ad_len        = 32'h0;
        msg_len       = 32'h0;
        key           = 128'h0;
        nonce         = 128'h0;
        expected_tag  = 128'h0;
        data_in       = 64'h0;
        data_in_valid = 1'b0;
        data_out_ready= 1'b1;
        pt_rd_addr    = 8'h0;
        total_pass    = 0;
        total_fail    = 0;

        // Load KAT memory
        $readmemh("tb/vectors/aead_kat.mem", kat_mem);

        // Open log file
        log_fd = $fopen("results/kat/rtl_aead_full_pass.log", "w");
        if (log_fd == 0) begin
            $display("[WARNING] Cannot open results/kat/rtl_aead_full_pass.log");
        end else begin
            $fdisplay(log_fd, "# tb_aead_full.sv NIST SP 800-232 AEAD-128 Exhaustive KAT Log");
            $fdisplay(log_fd, "# [SPEC] F1 fix: all 1089 vectors exercised");
            $fdisplay(log_fd, "# Tests per vector: Encrypt, Decrypt-valid, Decrypt-corrupt-tag, Decrypt-corrupt-CT");
        end

        // Hardware reset
        #(CLK_PERIOD * 5);
        @(negedge clk);
        rst_n = 1'b1;
        #(CLK_PERIOD * 2);

        $display("================================================================================");
        $display("tb_aead_full.sv — NIST SP 800-232 Ascon-AEAD128 Exhaustive KAT");
        $display("Vectors: 1089 | Tests per vector: 4 | Total assertions: %0d", 1089 * 4);
        $display("================================================================================");

        for (int v = 0; v < NUM_VECTORS; v = v + 1) begin
            // ------------------------------------------------------------------
            // Extract vector fields from kat_mem
            // ------------------------------------------------------------------
            automatic integer base       = v * RECORD_WORDS;
            automatic integer v_count    = kat_mem[base + 0];
            automatic integer v_ad_len   = kat_mem[base + 1];
            automatic integer v_pt_len   = kat_mem[base + 2];
            automatic reg [127:0] v_key   = be_words_to_rtl128(base + 4);
            automatic reg [127:0] v_nonce = be_words_to_rtl128(base + 8);
            automatic reg [127:0] v_tag   = be_words_to_rtl128(base + 12);
            automatic integer ad_base    = base + 16;
            automatic integer pt_base    = base + 24;
            automatic integer ct_base    = base + 32;

            // Edge-case annotation
            automatic bit is_edge = (v_ad_len inside {0,1,7,8,9,15,16,17,31,32} ||
                                     v_pt_len inside {0,1,7,8,9,15,16,17,31,32});

            // ==================================================================
            // TEST A: Encrypt
            // ==================================================================
            dut_reset();

            key         = v_key;
            nonce       = v_nonce;
            ad_len      = v_ad_len;
            msg_len     = v_pt_len;
            decrypt     = 1'b0;
            expected_tag= 128'h0;

            @(negedge clk);
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;

            stream_bytes(ad_base, v_ad_len);
            if (v_pt_len > 0)
                fork
                    stream_bytes(pt_base, v_pt_len);
                    collect_ct(v_pt_len);
                join
            else
                collect_ct(0);

            wait (done == 1'b1);
            @(negedge clk);

            begin
                automatic bit enc_ok = (tag_out === v_tag);
                if (v_pt_len > 0) enc_ok = enc_ok & ct_matches(ct_base, v_pt_len);

                if (enc_ok) begin
                    total_pass++;
                    if (is_edge) $display("  [PASS][EDGE] Encrypt Count=%0d AD=%0d PT=%0d",
                                          v_count, v_ad_len, v_pt_len);
                end else begin
                    total_fail++;
                    $display("  [FAIL] Encrypt Count=%0d AD=%0d PT=%0d", v_count, v_ad_len, v_pt_len);
                    $display("         got_tag=%h exp_tag=%h", tag_out, v_tag);
                    if (log_fd) $fdisplay(log_fd, "FAIL Encrypt Count=%0d", v_count);
                    $fatal(1, "AEAD encrypt mismatch at Count=%0d", v_count);
                end
            end

            // ==================================================================
            // TEST B: Decrypt with valid tag — expect tag_ok=1, plaintext released
            // ==================================================================
            dut_reset();

            key         = v_key;
            nonce       = v_nonce;
            ad_len      = v_ad_len;
            msg_len     = v_pt_len;
            decrypt     = 1'b1;
            expected_tag= v_tag;

            @(negedge clk);
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;

            stream_bytes(ad_base, v_ad_len);
            stream_bytes(ct_base, v_pt_len);  // Feed ciphertext as input

            wait (done == 1'b1 || error == 1'b1);
            @(negedge clk);

            begin
                automatic bit dec_ok;
                // Check tag_ok and error flags
                dec_ok = (tag_ok === 1'b1) && (error === 1'b0);

                // Verify plaintext from gate buffer if PT > 0
                if (v_pt_len > 0 && dec_ok) begin
                    automatic integer n_pt_words = (v_pt_len + 7) / 8;
                    for (int pi = 0; pi < n_pt_words; pi++) begin
                        automatic reg [63:0] exp_pt = build_data_word(pt_base, pi * 8);
                        pt_rd_addr = pi;
                        #10;
                        if (pt_rd_valid !== 1'b1) begin
                            dec_ok = 0;
                        end else begin
                            // Compare valid bytes
                            automatic integer vb = (pi == n_pt_words-1 && (v_pt_len%8)!=0) ?
                                                   (v_pt_len % 8) : 8;
                            automatic reg [63:0] mask_pt = (vb == 8) ? 64'hFFFFFFFFFFFFFFFF :
                                                           ((64'h1 << (vb*8)) - 64'h1);
                            if ((pt_rd_data & mask_pt) !== (exp_pt & mask_pt)) begin
                                dec_ok = 0;
                                $display("  [DEBUG PT MISMATCH] pi=%0d got=%h exp=%h mask=%h",
                                         pi, pt_rd_data, exp_pt, mask_pt);
                            end
                        end
                    end
                end

                if (dec_ok) begin
                    total_pass++;
                end else begin
                    total_fail++;
                    $display("  [FAIL] Decrypt-valid Count=%0d tag_ok=%b error=%b",
                             v_count, tag_ok, error);
                    if (log_fd) $fdisplay(log_fd, "FAIL Decrypt-valid Count=%0d", v_count);
                    $fatal(1, "AEAD decrypt-valid mismatch at Count=%0d", v_count);
                end
            end

            // ==================================================================
            // TEST C: Decrypt with corrupted tag — expect tag_ok=0, error=1,
            //         NO plaintext released (security property)
            // ==================================================================
            dut_reset();

            key         = v_key;
            nonce       = v_nonce;
            ad_len      = v_ad_len;
            msg_len     = v_pt_len;
            decrypt     = 1'b1;
            // Flip bit 0 of tag to corrupt it
            expected_tag= v_tag ^ 128'h1;

            @(negedge clk);
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;

            stream_bytes(ad_base, v_ad_len);
            stream_bytes(ct_base, v_pt_len);

            wait (done == 1'b1 || error == 1'b1);
            @(negedge clk);

            begin
                automatic bit tamper_ok;
                tamper_ok = (tag_ok === 1'b0) && (error === 1'b1);
                // Security: pt_gate must not release plaintext
                if (v_pt_len > 0) begin
                    pt_rd_addr = 0;
                    #5;
                    if (pt_rd_valid !== 1'b0) tamper_ok = 0;
                end
                if (tamper_ok) begin
                    total_pass++;
                end else begin
                    total_fail++;
                    $display("  [FAIL] Decrypt-corrupt-tag Count=%0d tag_ok=%b error=%b pt_valid=%b",
                             v_count, tag_ok, error, pt_rd_valid);
                    if (log_fd) $fdisplay(log_fd, "FAIL Decrypt-corrupt-tag Count=%0d", v_count);
                    $fatal(1, "Security failure: corrupt tag not caught at Count=%0d", v_count);
                end
            end

            // ==================================================================
            // TEST D: Decrypt with one CT byte corrupted (if PT_LEN > 0)
            //         Expect: error=1, no plaintext
            // ==================================================================
            if (v_pt_len > 0) begin
                dut_reset();

                key         = v_key;
                nonce       = v_nonce;
                ad_len      = v_ad_len;
                msg_len     = v_pt_len;
                decrypt     = 1'b1;
                expected_tag= v_tag;

                @(negedge clk);
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;

                stream_bytes(ad_base, v_ad_len);

                // Stream CT with first byte flipped
                begin
                    automatic reg [63:0] first_ct_word = build_data_word(ct_base, 0);
                    automatic reg [63:0] corrupted      = first_ct_word ^ 64'h01; // flip LSB
                    wait (data_in_ready == 1'b1);
                    @(negedge clk);
                    data_in       = corrupted;
                    data_in_valid = 1'b1;
                    @(negedge clk);
                    data_in_valid = 1'b0;
                    // Stream remaining CT bytes normally
                    if (v_pt_len > 8)
                        stream_bytes(ct_base + 2, v_pt_len - 8);
                end

                wait (done == 1'b1 || error == 1'b1);
                @(negedge clk);

                begin
                    automatic bit corrupt_ct_ok;
                    corrupt_ct_ok = (error === 1'b1);
                    pt_rd_addr = 0;
                    #5;
                    if (pt_rd_valid !== 1'b0) corrupt_ct_ok = 0;

                    if (corrupt_ct_ok) begin
                        total_pass++;
                    end else begin
                        total_fail++;
                        $display("  [FAIL] Decrypt-corrupt-CT Count=%0d error=%b pt_valid=%b",
                                 v_count, error, pt_rd_valid);
                        if (log_fd) $fdisplay(log_fd, "FAIL Decrypt-corrupt-CT Count=%0d", v_count);
                        $fatal(1, "Security failure: corrupt CT not caught at Count=%0d", v_count);
                    end
                end
            end else begin
                // PT=0: no CT to corrupt; count as trivially passed
                total_pass++;
            end

            // Progress every 100 vectors
            if ((v + 1) % 100 == 0)
                $display("  Progress: %0d / %0d vectors  (PASS=%0d FAIL=%0d)",
                         v + 1, NUM_VECTORS, total_pass, total_fail);

        end // for v

        // -----------------------------------------------------------------------
        // Summary
        // -----------------------------------------------------------------------
        $display("\n================================================================================");
        $display("tb_aead_full.sv — FINAL RESULT");
        $display("================================================================================");
        $display("Total vectors tested:  %0d", NUM_VECTORS);
        $display("Total assertions PASS: %0d", total_pass);
        $display("Total assertions FAIL: %0d", total_fail);
        $display("================================================================================");

        if (log_fd) begin
            $fdisplay(log_fd, "");
            $fdisplay(log_fd, "TOTAL_VECTORS=%0d TOTAL_PASS=%0d TOTAL_FAIL=%0d",
                      NUM_VECTORS, total_pass, total_fail);
            $fdisplay(log_fd, "RESULT=%s", (total_fail == 0) ? "PASS" : "FAIL");
            $fclose(log_fd);
        end

        if (total_fail == 0) begin
            $display("ASCON-AEAD128 EXHAUSTIVE KAT: 100%% PASS — ALL 1089 VECTORS VERIFIED");
            $finish;
        end else begin
            $display("ASCON-AEAD128 EXHAUSTIVE KAT: FAILED with %0d errors", total_fail);
            $fatal(1, "tb_aead_full: %0d failures", total_fail);
        end
    end

endmodule

